package com.neotvos.support;

import java.io.*;import java.net.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.interfaces.*;import java.security.spec.*;import java.math.BigInteger;import javax.crypto.Cipher;import java.util.*;

/** Single-channel ADB transport. No arbitrary commands are exposed by the UI. */
public final class AdbClient implements Closeable {
 public interface Wire extends Closeable {void readFully(byte[] b)throws Exception;void write(byte[] b)throws Exception;}
 public interface Progress {void transferred(long sent,long total);}
 static final int CNXN=0x4e584e43,AUTH=0x48545541,OPEN=0x4e45504f,OKAY=0x59414b4f,CLSE=0x45534c43,WRTE=0x45545257,STLS=0x534c5453;
 private final Wire wire;private int id=1;private volatile boolean closed;
 public AdbClient(Wire wire,KeyPair keys)throws Exception{this.wire=wire;try{send(CNXN,0x01000000,4096,"host::\0".getBytes(StandardCharsets.UTF_8));boolean signed=false;long until=System.currentTimeMillis()+90000;
  while(System.currentTimeMillis()<until){Packet p=read();if(p.command==CNXN)return;if(p.command==STLS)throw new IOException("This port requires paired TLS debugging. Use the TV's Network ADB port, or connect by USB first and enable network ADB.");if(p.command==AUTH&&p.a==1){if(!signed){send(AUTH,2,0,sign(keys.getPrivate(),p.data));signed=true;}else send(AUTH,3,0,publicKey((RSAPublicKey)keys.getPublic()));}else throw new IOException("Unexpected ADB handshake");}throw new IOException("Approve Allow debugging on the TV, then reconnect.");
 }catch(Exception e){close();throw e;}}
 public static Wire tcp(String host,int port)throws Exception{Socket s=new Socket();s.connect(new InetSocketAddress(host,port),5000);s.setSoTimeout(90000);s.setTcpNoDelay(true);s.setKeepAlive(true);DataInputStream in=new DataInputStream(s.getInputStream());OutputStream out=s.getOutputStream();return new Wire(){public void readFully(byte[] b)throws Exception{in.readFully(b);}public void write(byte[] b)throws Exception{out.write(b);out.flush();}public void close()throws IOException{s.close();}};}
 static byte[] sign(PrivateKey key,byte[] token)throws Exception{if(token.length!=20)throw new IOException("Invalid ADB challenge");byte[] prefix={0x30,0x21,0x30,0x09,0x06,0x05,0x2b,0x0e,0x03,0x02,0x1a,0x05,0x00,0x04,0x14};byte[] d=new byte[35];System.arraycopy(prefix,0,d,0,15);System.arraycopy(token,0,d,15,20);Cipher c=Cipher.getInstance("RSA/ECB/PKCS1Padding");c.init(Cipher.ENCRYPT_MODE,key);return c.doFinal(d);}
 static byte[] little(BigInteger n){byte[] b=n.toByteArray(),out=new byte[256];for(int i=0;i<256&&i<b.length;i++)out[i]=b[b.length-1-i];return out;}
 static byte[] publicKey(RSAPublicKey key){BigInteger n=key.getModulus(),r=BigInteger.ONE.shiftLeft(32);ByteBuffer b=ByteBuffer.allocate(524).order(ByteOrder.LITTLE_ENDIAN);b.putInt(64).putInt(r.subtract(n.mod(r).modInverse(r)).intValue());b.put(little(n)).put(little(BigInteger.ONE.shiftLeft(4096).mod(n))).putInt(key.getPublicExponent().intValue());return (Base64.getEncoder().encodeToString(b.array())+" neo-support@android\0").getBytes(StandardCharsets.US_ASCII);}
 public static KeyPair keys(File dir)throws Exception{File privateFile=new File(dir,"adb-private.pk8"),publicFile=new File(dir,"adb-public.der");if(privateFile.exists()&&publicFile.exists()){KeyFactory f=KeyFactory.getInstance("RSA");return new KeyPair(f.generatePublic(new X509EncodedKeySpec(java.nio.file.Files.readAllBytes(publicFile.toPath()))),f.generatePrivate(new PKCS8EncodedKeySpec(java.nio.file.Files.readAllBytes(privateFile.toPath()))));}KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);KeyPair pair=g.generateKeyPair();java.nio.file.Files.write(privateFile.toPath(),pair.getPrivate().getEncoded());java.nio.file.Files.write(publicFile.toPath(),pair.getPublic().getEncoded());return pair;}
 static final class Packet{int command,a,b;byte[] data;}
 private Packet read()throws Exception{byte[] header=new byte[24];wire.readFully(header);ByteBuffer b=ByteBuffer.wrap(header).order(ByteOrder.LITTLE_ENDIAN);Packet p=new Packet();p.command=b.getInt();p.a=b.getInt();p.b=b.getInt();int length=b.getInt(),sum=b.getInt(),magic=b.getInt();if(magic!=~p.command||length<0||length>1048576)throw new IOException("Invalid ADB packet");p.data=new byte[length];wire.readFully(p.data);int actual=0;for(byte v:p.data)actual+=v&255;if(actual!=sum)throw new IOException("ADB checksum mismatch");return p;}
 private void send(int command,int a,int b,byte[] data)throws Exception{if(closed)throw new IOException("Disconnected");int sum=0;for(byte v:data)sum+=v&255;ByteBuffer h=ByteBuffer.allocate(24+data.length).order(ByteOrder.LITTLE_ENDIAN);h.putInt(command).putInt(a).putInt(b).putInt(data.length).putInt(sum).putInt(~command).put(data);wire.write(h.array());}
 public synchronized String shell(String command)throws Exception{try{return exchange("shell:"+command,null,0,null);}catch(Exception e){close();throw e;}}
 public synchronized String install(InputStream apk,long length,Progress progress)throws Exception{try{return exchange("exec:cmd package install -r --user 0 -S "+length,apk,length,progress);}catch(Exception e){close();throw e;}}
 public synchronized void uploadInventory(InputStream bytes,long length)throws Exception{if(length<=0||length>1048576)throw new IOException("Invalid inventory helper size");try{exchange("exec:sh -c 'head -c "+length+" > /data/local/tmp/neo-support-inventory.jar'",bytes,length,null);}catch(Exception e){close();throw e;}}
 public synchronized String enableTcp()throws Exception{return exchange("tcpip:5555",null,0,null);}
 private String exchange(String service,InputStream input,long length,Progress progress)throws Exception{int local=id++,remote=0;ByteArrayOutputStream result=new ByteArrayOutputStream();send(OPEN,local,0,(service+"\0").getBytes(StandardCharsets.UTF_8));Packet p;while(true){p=read();if(p.b!=local && (p.command==CLSE||p.command==OKAY))continue;if(p.command==CLSE)throw new IOException("TV rejected service: "+service+" [channel "+p.a+","+p.b+"]");if(p.command!=OKAY||p.b!=local)throw new IOException("ADB open was not acknowledged");remote=p.a;break;}
  long sent=0;byte[] buffer=new byte[4096];while(input!=null&&sent<length){int n=input.read(buffer,0,(int)Math.min(buffer.length,length-sent));if(n<0)throw new EOFException("APK ended early");send(WRTE,local,remote,Arrays.copyOf(buffer,n));boolean ack=false;while(!ack){p=read();if(p.b!=local)throw new IOException("ADB channel mismatch");if(p.command==OKAY)ack=true;else if(p.command==WRTE){append(result,p.data);send(OKAY,local,remote,new byte[0]);}else if(p.command==CLSE)throw new IOException("Install stopped: "+result.toString("UTF-8"));else throw new IOException("Unexpected ADB reply");}sent+=n;if(progress!=null)progress.transferred(sent,length);}
  while(true){p=read();if(p.b!=local)throw new IOException("ADB channel mismatch");if(p.command==WRTE){append(result,p.data);send(OKAY,local,remote,new byte[0]);}else if(p.command==CLSE){send(CLSE,local,remote,new byte[0]);return result.toString("UTF-8");}else if(p.command!=OKAY)throw new IOException("Unexpected ADB output");}
 }
 private static void append(ByteArrayOutputStream out,byte[] bytes)throws IOException{if(out.size()+bytes.length>16*1024*1024)throw new IOException("TV response too large");out.write(bytes);}
 public boolean connected(){return !closed;}
 public void close(){closed=true;try{wire.close();}catch(Exception ignored){}}
}
